#!/data/data/com.termux/files/usr/bin/bash
set -euo pipefail
V=OBSIDIANTI_SWORD1_PALM_CLEARANCE_v2.0.39
SELF="$(realpath "$0")"
ENTRY_SHA256="$(sha256sum "$SELF" | cut -d ' ' -f1)"
PAYLOAD_SHA256="d2c6affcbab4114b9eb52730472137941d50c2eccdfff3828a53617e6c2fa9c4"
printf 'CAMPAIGN=%s\nAUTHORITY=TERMUX_GIT_ONLY\nENTRY_SHA256=%s\nPAYLOAD_SHA256=%s\n' "$V" "$ENTRY_SHA256" "$PAYLOAD_SHA256"
export PYTHONDONTWRITEBYTECODE=1
TEMP="$(mktemp -d "${TMPDIR:-${PREFIX:-/data/data/com.termux/files/usr}/tmp}/obs-palm-v239.XXXXXXXX")"
trap 'rm -rf "$TEMP"' EXIT
base64 -d > "$TEMP/payload.tar.gz" <<'OBSIDIANTI_PALM_CLEARANCE_V239_PAYLOAD'

OBSIDIANTI_PALM_CLEARANCE_V239_PAYLOAD
printf '%s  %s\n' "$PAYLOAD_SHA256" "$TEMP/payload.tar.gz" | sha256sum -c -
python3 - "$TEMP/payload.tar.gz" <<'PY_VALIDATE'
import sys,tarfile
with tarfile.open(sys.argv[1],'r:gz') as t:
 names=[x.name for x in t]
 expected={"packet/driver.py","packet/fix.py","packet/test.py","packet/contract.json","packet/manifest.json"}
 if set(names)!=expected:raise SystemExit('BLOCKED_PAYLOAD_MEMBER_ALLOWLIST_'+str(names))
 if any(not x.isfile() or x.issym() or x.islnk() for x in t):raise SystemExit('BLOCKED_NONREGULAR_PAYLOAD')
PY_VALIDATE
tar -xzf "$TEMP/payload.tar.gz" -C "$TEMP"
python3 -B "$TEMP/packet/driver.py" "$TEMP/packet" "$SELF" "$ENTRY_SHA256"
